drop index if exists public.idx_grammar_points_level; drop index if exists public.idx_kanji_level; drop index if exists public.idx_vocabulary_level; create index if not exists content_translations_pending_idx on public.content_translations (status, source_type, updated_at) where status in ('pending','processing'); create index if not exists vocabulary_published_level_order_idx on public.vocabulary (level, sort_order) where is_published=true; create index if not exists kanji_published_level_order_idx on public.kanji (level, sort_order) where is_published=true;
